#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string str;
    cin >> str;

    const int n = static_cast<int>(str.size());
    if (n < 2) {
        cout << 0 << '\n';
        return 0;
    }

    vector<int> sa(n), rank(n), buffer(n);
    vector<int> count(256, 0);

    for (unsigned char c : str)
        ++count[c];

    for (int i = 1; i < 256; ++i)
        count[i] += count[i - 1];

    for (int i = n - 1; i >= 0; --i)
        buffer[--count[static_cast<unsigned char>(str[i])]] = i;

    sa.swap(buffer);

    int classes = 1;
    rank[sa[0]] = classes;
    for (int i = 1; i < n; ++i) {
        if (str[sa[i]] != str[sa[i - 1]])
            ++classes;
        rank[sa[i]] = classes;
    }

    for (int len = 1; classes < n && len < n; len <<= 1) {
        count.assign(classes + 1, 0);

        for (int suffix : sa) {
            int key = suffix + len < n ? rank[suffix + len] : 0;
            ++count[key];
        }

        int sum = 0;
        for (int &x : count) {
            int frequency = x;
            x = sum;
            sum += frequency;
        }

        for (int suffix : sa) {
            int key = suffix + len < n ? rank[suffix + len] : 0;
            buffer[count[key]++] = suffix;
        }

        count.assign(classes + 1, 0);
        for (int suffix : buffer)
            ++count[rank[suffix]];

        sum = 0;
        for (int &x : count) {
            int frequency = x;
            x = sum;
            sum += frequency;
        }

        for (int suffix : buffer)
            sa[count[rank[suffix]]++] = suffix;

        int newClasses = 1;
        buffer[sa[0]] = newClasses;

        for (int i = 1; i < n; ++i) {
            int current = sa[i];
            int previous = sa[i - 1];

            int currentSecond =
                current + len < n ? rank[current + len] : 0;
            int previousSecond =
                previous + len < n ? rank[previous + len] : 0;

            if (rank[current] != rank[previous] ||
                currentSecond != previousSecond) {
                ++newClasses;
            }

            buffer[current] = newClasses;
        }

        rank.swap(buffer);
        classes = newClasses;
    }

    int longest = 0;
    int matched = 0;

    for (int i = 0; i < n; ++i) {
        int position = rank[i] - 1;

        if (position == 0) {
            matched = 0;
            continue;
        }

        int j = sa[position - 1];

        while (i + matched < n && j + matched < n &&
               str[i + matched] == str[j + matched]) {
            ++matched;
        }

        longest = max(longest, matched);

        if (matched > 0)
            --matched;
    }

    cout << (longest >= 2 ? longest : 0) << '\n';
    return 0;
}

