    cin >> str;

    int n = static_cast<int>(str.size());
    if (n < 2) {
        cout << 0 << '\n';
        return 0;
    }

    vector<int> suffixArray(n), rank(n), nextRank(n);
    iota(suffixArray.begin(), suffixArray.end(), 0);

    for (int i = 0; i < n; ++i)
        rank[i] = static_cast<unsigned char>(str[i]);

    for (int length = 1; length < n; length <<= 1) {
        sort(suffixArray.begin(), suffixArray.end(),
             [&](int a, int b) {
                 if (rank[a] != rank[b])
                     return rank[a] < rank[b];

                 int rankA = (a + length < n) ? rank[a + length] : -1;
                 int rankB = (b + length < n) ? rank[b + length] : -1;
                 return rankA < rankB;
             });

        nextRank[suffixArray[0]] = 0;

        for (int i = 1; i < n; ++i) {
            int previous = suffixArray[i - 1];
            int current = suffixArray[i];

            bool different =
                rank[previous] != rank[current] ||
                ((previous + length < n) ? rank[previous + length] : -1) !=
                ((current + length < n) ? rank[current + length] : -1);

            nextRank[current] = nextRank[previous] + different;
        }

        rank.swap(nextRank);

        if (rank[suffixArray.back()] == n - 1)
            break;

        if (length > n / 2)
            break;
    }

    int longest = 0;
    int matched = 0;

    for (int i = 0; i < n; ++i) {
        int position = rank[i];

        if (position == n - 1) {
            matched = 0;
            continue;
        }

        int j = suffixArray[position + 1];

        while (i + matched < n && j + matched < n &&
               str[i + matched] == str[j + matched]) {
            ++matched;
        }

        longest = max(longest, matched);

        if (matched > 0)
            --matched;
    }

    cout << longest << '\n';
    return 0;
}

