    if (n < 2) {
        cout << 0 << '\n';
        return 0;
    }

    vector<int> suffixArray(n), rank(n), nextRank(n);

    for (int i = 0; i < n; ++i) {
        suffixArray[i] = i;
        rank[i] = static_cast<unsigned char>(str[i]);
    }

    for (int length = 1;; length *= 2) {
        sort(suffixArray.begin(), suffixArray.end(), [&](int a, int b) {
            if (rank[a] != rank[b])
                return rank[a] < rank[b];

            int rankA = (a + length < n) ? rank[a + length] : -1;
            int rankB = (b + length < n) ? rank[b + length] : -1;
            return rankA < rankB;
        });

        nextRank[suffixArray[0]] = 0;

        for (int i = 1; i < n; ++i) {
            int previous = suffixArray[i - 1];
            int current = suffixArray[i];

            bool different = rank[previous] != rank[current];

            int previousSecond =
                (previous + length < n) ? rank[previous + length] : -1;
            int currentSecond =
                (current + length < n) ? rank[current + length] : -1;

            if (previousSecond != currentSecond)
                different = true;

            nextRank[current] = nextRank[previous] + different;
        }

        rank.swap(nextRank);

        if (rank[suffixArray.back()] == n - 1 || length >= n)
            break;
    }

    vector<int> position(n);
    for (int i = 0; i < n; ++i)
        position[suffixArray[i]] = i;

    int longest = 0;
    int commonLength = 0;

    for (int i = 0; i < n; ++i) {
        int suffixPosition = position[i];

        if (suffixPosition == n - 1) {
            commonLength = 0;
            continue;
        }

        int j = suffixArray[suffixPosition + 1];

        while (i + commonLength < n &&
               j + commonLength < n &&
               str[i + commonLength] == str[j + commonLength]) {
            ++commonLength;
        }

        longest = max(longest, commonLength);

        if (commonLength > 0)
            --commonLength;
    }

    cout << longest << '\n';
    return 0;
}

