#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string str;
    if (!(cin >> str) || str.size() < 2) {
        cout << 0 << '\n';
        return 0;
    }

    const int n = static_cast<int>(str.size());
    vector<int> sa(n), rank(n), work(n), count(n);

    array<int, 256> charCount{};
    for (unsigned char c : str)
        ++charCount[c];

    for (int i = 1; i < 256; ++i)
        charCount[i] += charCount[i - 1];

    for (int i = n - 1; i >= 0; --i)
        sa[--charCount[static_cast<unsigned char>(str[i])]] = i;

    int classes = 1;
    rank[sa[0]] = 0;
    for (int i = 1; i < n; ++i) {
        if (str[sa[i]] != str[sa[i - 1]])
            ++classes;
        rank[sa[i]] = classes - 1;
    }

    for (int length = 1; length < n && classes < n; length <<= 1) {
        int p = 0;

        for (int i = max(0, n - length); i < n; ++i)
            work[p++] = i;

        for (int suffix : sa) {
            if (suffix >= length)
                work[p++] = suffix - length;
        }

        fill(count.begin(), count.begin() + classes, 0);
        for (int suffix : work)
            ++count[rank[suffix]];

        for (int i = 1; i < classes; ++i)
            count[i] += count[i - 1];

        for (int i = n - 1; i >= 0; --i) {
            int suffix = work[i];
            sa[--count[rank[suffix]]] = suffix;
        }

        int newClasses = 1;
        work[sa[0]] = 0;

        for (int i = 1; i < n; ++i) {
            int current = sa[i];
            int previous = sa[i - 1];

            if (rank[current] != rank[previous] ||
                (current + length < n ? rank[current + length] : -1) !=
                (previous + length < n ? rank[previous + length] : -1)) {
                ++newClasses;
            }

            work[current] = newClasses - 1;
        }

        rank.swap(work);
        classes = newClasses;

        if (length > n / 2)
            break;
    }

    int answer = 0;
    int common = 0;

    for (int i = 0; i < n; ++i) {
        int position = rank[i];

        if (position == 0) {
            common = 0;
            continue;
        }

        int previousSuffix = sa[position - 1];

        while (i + common < n &&
               previousSuffix + common < n &&
               str[i + common] == str[previousSuffix + common]) {
            ++common;
        }

        answer = max(answer, common);

        if (common > 0)
            --common;
    }

    cout << answer << '\n';
    return 0;
}

